import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';
class TrainingLibraryScreen extends ConsumerWidget{const TrainingLibraryScreen({super.key});static const lessons=[('Reward marker basics','Pair a consistent marker with a reward in short, calm sessions.',['Choose a quiet setting.','Mark a behavior the pet offers naturally.','Deliver a reward immediately.','Stop after a few successful repetitions.']),('Name response','Reward voluntary attention and keep practice brief.',['Say the name once in a calm voice.','Reward when the pet looks toward you.','Practice in low-distraction settings.','Gradually add distance and mild distractions.']),('Settle on a mat','Reward calm choices and allow the pet to move away.',['Place a mat in a quiet space.','Reward voluntary investigation.','Reward relaxed pauses without forcing a position.','Keep the session short and end before frustration.']),('Loose-leash foundations','Practice in a low-distraction area and reward slack leash.',['Use properly fitted equipment.','Start in a familiar, low-distraction place.','Reward when the leash is loose.','Pause and reset if the pet becomes overwhelmed.']),('Carrier comfort','Let the pet explore the carrier at their own pace; never force entry.',['Place the carrier in a familiar room.','Reward voluntary approaches.','Allow the pet to leave freely.','Build duration gradually over multiple sessions.'])];@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);return Scaffold(appBar:AppBar(title:const Text('Positive-reinforcement lessons')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Short, reward-based practice ideas. Adapt to your pet and stop if they show stress.'),const SizedBox(height:12),...lessons.map((e){final id='lesson-${e.$1.toLowerCase().replaceAll(' ','-')}';final saved=c.items('favorites').any((x)=>x['id']==id);return Card(child:ExpansionTile(title:Text(e.$1,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(e.$2),trailing:IconButton(icon:Icon(saved?Icons.bookmark:Icons.bookmark_border),onPressed:()=>saved?c.delete('favorites',id):c.save('favorites',{'id':id,'contentId':id,'contentType':'training','title':e.$1,'createdAt':DateTime.now().toIso8601String()})),children:[for(var i=0;i<e.$3.length;i++)ListTile(leading:CircleAvatar(radius:13,child:Text('${i+1}')),title:Text(e.$3[i])),const Padding(padding:EdgeInsets.all(12),child:Text('Stop if your pet shows fear, distress or discomfort. Do not use force or punishment. Seek a qualified trainer or veterinary behavior professional when needed.'))]));})]));}}
